  "series-button.css": ".history-pog .series-history-open{margin-left:auto;border:1px solid #4c8fff;border-radius:5px;background:#2468e7;color:#fff;padding:9px 13px;font-size:10px;font-weight:800;cursor:pointer;box-shadow:0 6px 18px rgba(36,104,231,.22)}.history-pog .series-history-open:hover{background:#397cf3;border-color:#78a7ff}.history-pog .series-history-open:focus-visible{outline:3px solid rgba(120,167,255,.4);outline-offset:2px}@media(max-width:700px){.history-pog .series-history-open{width:100%;margin:8px 0 0;padding:12px}}\r\n",
